// Shared physical artwork. All coordinates refer to the terminal contract in model.mjs.
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
const label=(x,y,v,cls='micro')=>`<text x="${x}" y="${y}" class="${cls}" text-anchor="middle">${esc(v)}</text>`;
const poles=(y,screws)=>Array.from({length:6},(_,i)=>`<circle class="screw" cx="${16+i*25}" cy="${y}" r="6"/>${screws?`<path class="screw-slot" d="M${12+i*25} ${y}h8"/>`:''}`).join('');
export const visuals={
 pot:c=>`<path class="board" d="M-52 116h104v23H-52z"/><circle class="metal" cy="82" r="54"/><circle class="rim" cy="82" r="48"/><path class="rim" d="M-43 55l6 4M43 55l-6 4M-44 107l6-3M44 107l-6-3"/><path class="metal" d="M-48 123h12v25h-12zM-6 129h12v19H-6zM36 123h12v25H36z"/><path class="rim" d="M-29 45q29-14 58 0M-29 119q29 10 58 0"/><ellipse class="case-pad" cx="0" cy="82" rx="13" ry="9"/>${label(0,58,c.value.startsWith('CTS')?'CTS':'REAR VIEW')}${label(0,101,c.value.replace('CTS ',''),'part-value')}${label(-42,169,'3 / CW','terminal-label')}${label(0,190,'2 / WIPER','terminal-label')}${label(42,169,'1 / CCW','terminal-label')}`,
 humbucker:c=>`<path class="pickup-base" d="M-9 22h-8v28h8v43h-8v28h17v7h156v-7h16V93h-9V50h9V22h-16V4H0v18z"/><rect class="bobbin-dark" x="0" y="10" width="156" height="49" rx="9"/><rect class="bobbin-light" x="0" y="68" width="156" height="49" rx="9"/>${poles(34,false)}${poles(93,true)}${label(78,52,c.coils?'COIL A':'SLUG COIL','coil-label light-label')}${label(78,111,c.coils?'COIL B':'SCREW COIL','coil-label')}<path class="pickup-cable" d="M158 94H175Q180 94 180 103V118"/>`,
 singlecoil:c=>`<path class="pickup-base" d="M8 18h140l12 18v40l-12 18H8L-4 76V36z"/><rect class="bobbin-light" x="0" y="27" width="156" height="58" rx="26"/>${poles(56,false)}<path class="pickup-cable" d="M155 70h24v47"/>`,
 capacitor:c=>{const style=c.physicalStyle||'orangeDrop';return `<path class="lead" d="M-46 0h20m52 0h20"/>${style==='disc'?'<circle class="disc-body" r="20"/>':style==='film'?'<rect class="film-body" x="-29" y="-15" width="58" height="30" rx="2"/>':'<path class="cap-body" d="M-28-7Q-28-17-17-17H17Q28-17 28-7V7Q28 17 17 17H-17Q-28 17-28 7z"/>'}<path class="rim" d="M-19-10h38M-19 10h38"/>${label(0,-32,c.value,'part-value')}${c.productMark?label(0,34,c.productMark):''}`;},
 resistor:c=>`<path class="lead" d="M-46 0h18m56 0h18"/><path class="resistor-body" d="M-28-7l6-5h44l6 5V7l-6 5h-44l-6-5z"/><path class="resistor-band" d="M-17-10v20M-6-12v24M8-12v24M20-10v20"/>${label(0,-23,c.value,'part-value')}`,
 toggle:c=>{const closed=c.closedContacts||[],neck=closed.some(pair=>pair.includes(c.id+'.neck')),bridge=closed.some(pair=>pair.includes(c.id+'.bridge')),angle=neck&&bridge?0:neck?-28:bridge?28:0;return `<g class="toggle-hardware"><path class="switch-frame" d="M-22 4q0-12 12-12h20q12 0 12 12v25h-44z"/><path class="toggle-collar" d="M-16 3l8-6h16l8 6v18l-8 6H-8l-8-6z"/><path class="rim" d="M-12 5h24M-12 11h24M-12 17h24"/><path class="switch-wafer" d="M-66 32h132v47H-66z"/><path class="switch-leaf" d="M-55 42h110M-55 66h110"/><path class="toggle-leaf-support" d="M-67 36h134v8H-67zM-67 64h134v8H-67z"/><circle class="metal" cy="20" r="17"/><circle class="screw" cy="20" r="6"/><g class="toggle-lever"${c.showState?` transform="rotate(${angle} 0 20)" data-toggle-position="${esc(c.position)}"`:''}><path class="metal" d="M-6-20h12v40H-6z"/><path class="rim" d="M0-16v28"/></g>${Object.entries(c.terminals).filter(([key])=>key!=='ground').map(([key,t])=>`<path class="switch-lug ${key.startsWith('out')?'toggle-output common-lug':''}" d="M${t.x-6} 76h12v38h-12z"/><ellipse class="lug-hole" cx="${t.x}" cy="${t.y}" rx="3" ry="2"/>`).join('')}${label(0,58,'SOLDER SIDE','switch-orientation')}${label(-60,136,'NECK','terminal-label')}${label(0,156,'OUT N · OUT B','terminal-label')}${label(60,136,'BRIDGE','terminal-label')}</g>`;},
 jack:c=>`<circle class="board" cy="48" r="33"/><circle class="metal" cy="48" r="25"/><circle class="jack-hole" cy="48" r="14"/><path class="rim" d="M-20 36l8-9h24l8 9v24l-8 9h-24l-8-9z"/><path class="metal" d="M16 38l15-26 18 1 4 10-25 22M-19 48l-32-2-2 16 32 1"/><path class="rim" d="M25 39l8 28-18 13"/>${label(56,-4,'TIP / SIGNAL','terminal-label')}${label(-30,102,'SLEEVE / GROUND','terminal-label')}${label(0,128,'SOLDER SIDE')}`,
 ground:c=>`<path class="ground-symbol" d="M0 0v12m-16 0h32m-25 7h18m-13 7h8"/>`
};
visuals.dpdt=c=>`<g class="dpdt-hardware" data-actuator-state="${c.showState?c.position:'hardware'}"><path class="mechanical-link" d="M-30 75h60v14h-60z"/><rect class="switch-frame" x="-42" y="-16" width="84" height="91" rx="7"/><rect class="switch-wafer" x="-34" y="-8" width="68" height="73" rx="3"/><path class="rim" d="M0-5v66"/>${Object.entries(c.terminals).map(([key,t])=>`<path class="switch-lug ${key.endsWith('C')?'common-lug':''}" d="M${t.x-7} ${t.y-5}h14v10h-14z"/><ellipse class="lug-hole" cx="${t.x}" cy="${t.y}" rx="3" ry="2"/>${label(t.x+(t.x<0?-23:23),t.y+4,key,'terminal-label')}`).join('')}${label(0,94,'B: UNUSED','dpdt-caption')}${c.showState?`<path class="pushpull-actuator" data-mechanical-position="${c.position}" d="M-7 ${c.position==='up'?-31:-23}h14v7H-7z"/>`:''}</g>`;
visuals.pushpull=c=>visuals.pot(c)+`<rect class="metal" x="-37" y="213" width="74" height="85" rx="2"/><path class="board" d="M-33 218h66v70h-66z"/>${Object.entries(c.terminals).filter(([id])=>id.startsWith('switch')).map(([id,t])=>`<rect class="metal" x="${t.x-5}" y="${t.y-5}" width="10" height="10"/>${label(t.x+(t.x<0?-21:21),t.y+4,id.replace('switch',''),'terminal-label')}`).join('')}${label(0,320,'DPDT / SOLDER SIDE')}`;
visuals.p90=c=>`<rect class="bobbin-dark" x="0" y="10" width="156" height="100" rx="9"/>${poles(60,true)}<path class="pickup-cable" d="M156 85h24v33"/>`;
// A conventional 3-way and 5-way blade both have two poles, each with common + 3 throws.
// Position/contact behaviour belongs to the circuit definition, not to this visual.
const legacyBlade=c=>{const superSwitch=c.type==='superswitch',height=superSwitch?454:133;return `<rect class="metal" x="-19" y="-36" width="217" height="${height+35}" rx="3"/><rect class="board" x="-12" y="-14" width="197" height="${height}" rx="3"/><path class="metal" d="M86 32h20v33H86z"/><path class="rim" d="M35 52h119"/><circle class="screw" cx="96" cy="52" r="8"/><path class="lead" d="M200-60v24h-8"/>${Object.entries(c.terminals).filter(([k])=>k!=='ground').map(([key,t])=>`<path class="metal ${key.endsWith('C')?'common-lug':''}" d="M${t.x-7} ${t.y-7}h14v17h-14z"/>${label(t.x,t.y+29,key,'terminal-label')}`).join('')}${label(95,83,superSwitch?'4-POLE SUPER SWITCH':'STANDARD 2-POLE BLADE')}${label(95,99,'SOLDER SIDE · C = COMMON')}`;};
// Geometry projects the supplied closed pairs, never a position/contact table.
export function bladeMechanism(c){
 const banks=['A','B'].map(pole=>{
  const common=pole+'C',ref=c.id+'.'+common;
  const throws=(c.closedContacts||[]).flatMap(pair=>pair.includes(ref)?[pair.find(p=>p!==ref)?.split('.').at(-1)]:[]).filter(key=>key?.startsWith(pole)&&c.terminals[key]);
  return {pole,common,throws:[...new Set(throws)]};
 });
 const selected=banks.flatMap(bank=>bank.throws.map(key=>c.terminals[key].x)),fixed=Object.entries(c.terminals).filter(([key])=>/^[AB][123]$/.test(key)).map(([,t])=>t.x),centre=(Math.min(...fixed)+Math.max(...fixed))/2;
 return {banks,angle:selected.length?(selected.reduce((a,b)=>a+b,0)/selected.length-centre)*.9:0};
}
const blade=c=>{
 if(c.type==='superswitch')return legacyBlade(c);
 const five=c.type==='blade5'||c.label.includes('5-WAY'),mechanism=bladeMechanism(c);
 return `<g class="blade-hardware" data-blade-operation="${five?5:3}" data-illustration="lever-selector"><path class="blade-frame" fill-rule="evenodd" d="M-18 42H153V-39H184V138H153V72H-18zM161-18V35H176V-18zM161 78V118H176V78z"/><path class="blade-mounting-ear metal" d="M155-39h34v16h-34zM155 122h34v16h-34z"/><path class="rim" d="M-14 49H148M-14 65H148M157-30v155"/><path class="blade-spindle metal" d="M148 45h31v24h-31z"/>${mechanism.banks.map(({pole,common,throws})=>{
  const y=pole==='A'?-3:77,lane=pole==='A'?28:94,engaged=c.showState?new Set([common,...throws]):new Set();
  return `<g class="blade-contact-bank" data-pole="${pole}" data-wiper-throws="${c.showState?throws.join(' '):'hardware'}"><path class="blade-wafer" d="M-7 ${y+8}Q12 ${y}72 ${y}Q125 ${y}146 ${y+8}L139 ${y+24}Q72 ${y+32}-7 ${y+24}z"/><path class="blade-wafer-detail" d="M8 ${y+12}Q72 ${y-2}132 ${y+12}"/><path class="blade-stationary-contacts switch-leaf" d="M39 ${y+7}v13M81 ${y+3}v15M123 ${y+7}v13"/>${c.showState?throws.map(key=>{const a=c.terminals[common],b=c.terminals[key];return `<path class="blade-wiper" data-wiper-from="${esc(c.id+'.'+common)}" data-wiper-to="${esc(c.id+'.'+key)}" d="M${a.x} ${a.y}Q${a.x+8} ${lane} ${a.x+24} ${lane}L${b.x} ${lane}L${b.x} ${b.y}"/>`;}).join(''):''}${label(68,y+26,'POLE '+pole+(c.showState&&throws.length>1?' · BRIDGED':''),'blade-bank-label')}${Object.entries(c.terminals).filter(([k])=>k.startsWith(pole)).map(([key,t])=>`<path class="blade-lug ${key.endsWith('C')?'common-lug':''} ${engaged.has(key)?'blade-lug-closed':''}" data-physical-contact="${c.showState?(engaged.has(key)?'closed':'open'):'hardware'}" data-contact-terminal="${esc(c.id+'.'+key)}" d="M${t.x-5} ${t.y-11}h10v6h4v12l-4 5h-10l-4-5v-12h4z"/><ellipse class="lug-hole" cx="${t.x}" cy="${t.y}" rx="4" ry="2.5"/>${engaged.has(key)?`<circle class="blade-contact-halo" cx="${t.x}" cy="${t.y}" r="11"/>`:''}${label(t.x,t.y+(pole==='A'?-18:29),key.endsWith('C')?key+' COM':key,'blade-terminal-label').replace('<text',`<text data-label-terminal="${esc(c.id+'.'+key)}"`)}`).join('')}</g>`;
 }).join('')}<circle class="screw" cx="169" cy="-30" r="5"/><circle class="screw" cx="169" cy="130" r="5"/><path class="rim" d="M165-30h8M165 130h8"/><path class="blade-wafer-seam" d="M152 5v99"/><g class="blade-lever-assembly"${c.displaySelectorPosition?` data-selector-position="${esc(c.position)}" transform="rotate(${mechanism.angle} 168 57)"`:''}><path class="blade-lever" d="M164 57V18l-3-10h14l-3 10v39z"/><path class="blade-lever-slot" d="M168 14v32"/><path class="blade-lever-pointer" d="M161 8h14v-8h-14z"/><path class="blade-pivot-arm" d="M168 57l-21-10v20z"/><circle class="metal" cx="168" cy="57" r="12"/><circle class="screw" cx="168" cy="57" r="5"/></g><path class="lead" d="M200-60v28h-15"/>${label(168,99,five?'5-WAY':'3-WAY','blade-caption')}${label(66,57,'SOLDER SIDE','blade-orientation')}</g>`;
};
visuals.blade=blade;visuals.blade3=blade;visuals.blade5=blade;visuals.superswitch=blade;
visuals.network=c=>`<path class="lead" d="M-46 0h14m64 0h14"/><rect class="board" x="-32" y="-20" width="64" height="40"/>${label(0,4,c.value)}`;

// Shared physical pickup glyphs for descriptive configuration; no circuit or contact logic.
export function pickupLayoutArtwork(pickups){return `<svg class="pickup-layout-art" viewBox="0 0 ${pickups.length*180} 140" focusable="false" aria-hidden="true"><style>.pickup-layout-art .pickup-base{fill:#777;stroke:#aaa}.pickup-layout-art .bobbin-dark{fill:#333;stroke:#9a8156}.pickup-layout-art .bobbin-light{fill:#b9a373;stroke:#9a8156}.pickup-layout-art .screw{fill:#ddd;stroke:#777}.pickup-layout-art .screw-slot{stroke:#555}.pickup-layout-art :is(.pickup-cable,.coil-label,.light-label,.screw-slot){display:none}.pickup-layout-art text{fill:#ddd;font:12px sans-serif}</style>${pickups.map((p,n)=>`<g transform="translate(${n*180+12} 3)">${(p.type==='single'?visuals.singlecoil:visuals.humbucker)({})}<text x="78" y="135" text-anchor="middle">${esc(p.position)} · ${p.type==='single'?'S':'H'}</text></g>`).join('')}</svg>`;}

// A compact Inspector map projects actual contact pairs; it owns no switch truth.
export function switchContactMap(circuit,id){
 const part=circuit.components.find(p=>p.id===id);if(!part||!['dpdt','toggle','blade','blade3','blade5'].includes(part.type))return '';
 const pins=Object.entries(part.terminals).filter(([key])=>key!=='ground'),dpdt=part.type==='dpdt';
 const points=new Map(pins.map(([key,t],n)=>[id+'.'+key,dpdt?[key[0]==='A'?60:220,{1:35,C:85,2:135}[key[1]]]:[35+n%4*75,35+Math.floor(n/4)*95]]));
 const contacts=circuit.contacts.filter(pair=>pair[0].startsWith(id+'.'));
 return `<svg class="switch-contact-map" viewBox="0 0 320 185" role="img" aria-label="${esc(part.label+' '+part.position+' contact map; '+(dpdt?'Pole B intentionally unused':'common and throws'))}"><title>${esc(part.label)} · actual closed contacts</title>${contacts.map(([a,b])=>{const p=points.get(a),q=points.get(b);return `<path data-map-contact-from="${esc(a)}" data-map-contact-to="${esc(b)}" d="M${p.join(' ')}L${q.join(' ')}" class="map-contact"/>`;}).join('')}${pins.map(([key,t])=>{const p=points.get(id+'.'+key);return `<circle cx="${p[0]}" cy="${p[1]}" r="6" class="map-terminal"/><text x="${p[0]+11}" y="${p[1]+4}">${esc(key)}${key.endsWith('C')?' COM':''}</text>`;}).join('')}<text x="12" y="178">${dpdt?'Pole A · '+part.pickup+' split / Pole B unused':'Closed pairs from circuit contacts'}</text></svg>`;
}
